/* Fancy Table */
body .fancytable {
    border: 1px solid #dddddd;
    margin: 10px 20px;
    background: #ffffff;
    border-collapse: collapse;
}
body .fancytable thead th {
    background: #dddddd;
    margin: 0;
    color: #333333;
    text-align: center;

}
body .fancytable tbody td {
    border: 1px solid #dddddd;
    margin: 0;
    font-size: 1em !important;
    padding: 10px;
    min-height:60px;
}
body .fancytable tbody tr.highlighted_row > td {
    font-weight:800 !important;
    background-color:#ddd !important;
}
/* To alternate Row Color - unhide next line */
/* body .fancytable tr:nth-child(2n+1) { background: #eeeeee !important;} */

/* Alternating Row Table */
body .alternating-table {
    border: 1px solid #dddddd;
    background: #ffffff;
    border-collapse: collapse;
    width:100% !important;
}
body .alternating-table thead {
        border: 1px solid #eee;
}
body .alternating-table th {
    background: #dddddd;
    margin: 0;
    color: #333333;
    text-align: left;
    border: 1px solid #eee;
    padding:3px;
}
body .alternating-table td {
    border: 1px solid #dddddd;
    margin: 0;
    font-size: 1em !important;
    padding: 4px;
}
body .alternating-table tr:nth-child(2n+1) {
    background: #eeeeee !important;
}

/* 2-column container Table */
.table-container-2col td {
    padding:1rem;
}
.table-container-2col h3 {
    text-align:center;
}

/* Feature Table */
body .featuretable {
    margin: 14px auto;
    background: #ffffff;
    border-collapse: separate;
    border-spacing: 10px;
}
body .featuretable th {
    background: #42675e;
    color: #ffffff;
    padding: 6px;
    font-size: 1rem;
    text-align: center;
    border-radius: 10px 10px 0 0 !important;
}
body .featuretable td {
    border-bottom: 1px solid #dddddd;
    margin: 2px;
    font-size: 1em !important;
    padding: 4px;
    vertical-align: top;
}
body .featuretable tbody tr td img {
    margin: 0 auto;
}

/* Related Info Table */
body .related-info-table {
    color: #2b5e51;
    font-size: .8rem;
    border-radius: 0 0 10px 10px;
    border-collapse: collapse;
    Width:auto;
}
body .related-info-table th {
    color: #ffffff !important;
    font-size: .8rem;
    font-weight: 700;
    background: rgba(65, 114, 36, 1);
    padding:3px;
    text-align:center;
    border-bottom: 1px solid rgba(65, 114, 36, 1) !important;
    border-radius: 10px 10px 0 0;
}
body .related-info-table td {
    border: 1px solid #dddddd !important;
    border-radius: 0 0 8px 8px !important;
    padding: 6px;
    font-size:.8rem;
}
body .related-info-table ul {
    margin-left: 0;
    padding-inline-start: 10px !important;
}
body .related-info-table ul li {
    margin: 0;
    padding: 0 0 5px 15px;
    list-style: none;
   
}

/* Borderless Table Alternating Striped */
body .borderless-table-striped {
    background: #ffffff;
    border-collapse: collapse;
}
.borderless-table-striped th {
    border-bottom: 1px solid #333333;
    margin: 0;
    color: #333333;
    text-align: center;
    background-color: #ffffff;
}
.borderless-table-striped td {
    border-bottom: 1px solid #333333;
    margin: 0;
    font-size: 1em !important;
    padding: 6px;
}
.borderless-table-striped tr:nth-child(odd) {
    background: #eeeeee !important;

}

/* Borderless Table */
.borderless-table {
    margin: 10px;
    background: #ffffff;
    border-collapse: collapse;
}
.borderless-table th {
    border-bottom: 1px solid #333333;
    background-color: #ffffff;
    margin: 0;
    color: #333333;
    text-align: center;

}
.borderless-table td {
    border-bottom: 1px solid #333333;
    margin: 0;
    font-size: 1em !important;
    padding: 6px;
}
